_autoComplete(targetType) {
    this._removeOverlay();
    if (!this._connectorExist())
        return;
    switch (targetType) {
        case 'text':
            this._addText();
            break;
        case 'note':
            this._addNote();
            break;
        case 'frame':
            this._addFrame();
            break;
        default:
            this._addShape(targetType);
    }
    this.remove();
}

