_autoComplete(targetType) {
    this._removeOverlay();
    if (!this._connectorExist()) return;
    const source=this.currentSource;
    const current=source.elementBound;
    const width=targetType==='note'?(source instanceof NoteBlockModel?current.w:280):targetType==='text'?180:targetType==='frame'?320:current.w;
    const height=targetType==='note'?(source instanceof NoteBlockModel?current.h:200):targetType==='text'?48:targetType==='frame'?240:current.h;
    const target=this._getTargetXYWH(width,height);
    if(!target)return;
    this.dispatchEvent(new CustomEvent('brainz-quick-create',{bubbles:true,composed:true,detail:{source,bound:Bound.fromXYWH(target.xywh),targetType,connector:this.connector,endPosition:target.position}}));
    this.remove();
}

connectedCallback() {
    super.connectedCallback();
    this.disposables.addFromEvent(window,'keydown',event=>{
        if(event.metaKey || event.ctrlKey || event.altKey || event.isComposing)return;
        if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();this.remove();return;}
        const choices=[this._getCurrentSourceInfo().type,'note','text','roundedRect','ellipse','diamond','frame'];
        const type=event.key==='Enter'?choices[0]:choices[Number(event.key)-1];
        if(type){event.preventDefault();event.stopImmediatePropagation();this._autoComplete(type);}
    },true);

